//! Actual authored sources; no copied expected semantic model or findings.
pub const CASES:&[&str]=&["basic","first","followed","path","exempt","index_exempt","legacy","legacy_override","noncode","noncode_decl","settings","macro","returns"];
pub fn files(case:&str)->Vec<(&'static str,Vec<u8>)>{assert!(CASES.contains(&case));let types="#define CAPABILITIES(T) T/proc/capabilities()\n#define TRUE 1\n/datum/holder\n    var/datum/ref\n    var/list/items\n    var/datum/declared\n    var/list/owned\n    var/datum/linked\n    var/datum/map_only\n    var/datum/legacy\n/datum/holder/child\n/datum/other\n    var/datum/back\nCAPABILITIES(/datum/holder)\n    ref_one(nameof(declared))\n    owns_many(nameof(owned))\n    links(/datum/holder::linked, /datum/other::back)\n";
 let basic="/datum/holder/proc/check(datum/holder/H,unknown)\n    rel_clear(H, nameof(declared))\n    rel_clear(H, nameof(owned))\n    rel_clear(H, nameof(linked))\n    rel_set(H, nameof(ref), null)\n    rel_add(H, nameof(items), null, 1)\n    rel_clear(unknown, nameof(H.ref))\n    rel_clear(H, nameof(unknown.ref))\n";
 let source=match case{
 "first"=>"/datum/holder/proc/check(datum/holder/H)\n    rel_clear(H,nameof(v)); rel_add(H,nameof(v),null,1)\n",
 "followed"=>"/datum/holder/proc/check(datum/holder/H)\n    rel_clear(H,nameof(a)).field\n    rel_clear(H,nameof(b))[1]\n    rel_clear(H,nameof(c),rel_clear(H,nameof(d)))\n    (rel_clear(H,nameof(e)))\n    rel_move(H,nameof(f),H,nameof(g))\n    rel_private(H,nameof(h))\n    rel_is_private(H,nameof(i))\n",
 "path"=>"/datum/holder/proc/check(datum/holder/H)\n    rel_clear(H,nameof(/datum/holder::ref))\n    rel_move(H,nameof(/datum/holder::items),H,nameof(/datum/other::back))\n    rel_private(H,nameof(/datum/holder::legacy))\n",
 "legacy"|"legacy_override"=>"/datum/holder/relations()\n    . += owns(nameof(legacy))\n/datum/holder/proc/check(datum/holder/H)\n    rel_clear(H,nameof(legacy))\n    rel_clear(H,nameof(ref))\n",
 "noncode_decl"=>"/datum/holder/proc/check(datum/holder/H)\n    rel_clear(H,nameof(map_only))\n",
 "settings"=>"/datum/holder/proc/check(datum/holder/H)\n    set name = rel_clear(H,nameof(ref))\n    set desc = rel_clear(H,nameof(items)).field\n    rel_clear(H,nameof(legacy))\n",
 "macro"=>"#define WRITE_REL(H) rel_clear(H,nameof(ref))\n/datum/holder/proc/check(datum/holder/H)\n    WRITE_REL(H)\n    rel_clear(H,nameof(items))\n",
 "returns"=>"/proc/holder_result() as /datum/holder\n    return null\n/datum/holder/proc/method() as /datum/holder\n    return null\n/datum/holder/proc/check(datum/holder/H,unknown)\n    rel_clear(holder_result(),nameof(ref))\n    rel_clear(H.method(),nameof(items))\n    rel_clear(unknown.holder_result(),nameof(legacy))\n",
 _=>basic};let config=match case{"exempt"=>"[lint.rel_write_undeclared]\nexempt_files=['code/main.dm']\n","index_exempt"=>"[lint.rel_write_undeclared]\nexempt_files=['code/types.dm']\n",_=>""};let mut out=vec![("deepquarry.dme",b"#include \"code/types.dm\"\n#include \"code/main.dm\"\n".to_vec()),("code/types.dm",types.as_bytes().to_vec()),("code/main.dm",source.as_bytes().to_vec()),("tools/ci/lint_scopes.toml",config.as_bytes().to_vec())];
 if case=="legacy_override"{out[0].1.extend_from_slice(b"#include \"code/zz_override.dm\"\n");out.push(("code/zz_override.dm",b"#define OWN_NONE 0\n/datum/holder/relations()\n    . += owns(nameof(legacy), policy = OWN_NONE)\n".to_vec()));}
 if matches!(case,"noncode"|"noncode_decl"){out[0].1.extend_from_slice(b"#include \"maps/relation.dm\"\n");out.push(("maps/relation.dm",if case=="noncode"{b"/datum/holder/proc/map_write()\n    rel_clear(src,nameof(map_missing))\n".to_vec()}else{b"CAPABILITIES(/datum/holder)\n    ref_one(nameof(map_only))\n/datum/holder/proc/map_write()\n    rel_clear(src,nameof(map_only))\n".to_vec()}));}out
}
